head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vListEligtyTpCd = "F";
scwin.selRow = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID());
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        buttonSet.setInsertStatus();
        $c.elw.fn_searchCode();
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.searchGrdCode("DELIST_REAL_INVSTG_RSN_CD", dtl_Grd1);
        scwin.searchGrdCode("AUDT_OPIN_TP_CD", dtl_Grd2);
        scwin.searchGrdCode("LIST_ELIGTY_DELIB_RSLT_CD", dtl_Grd3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("회사를 선택하세요");
        } else {
            scwin.initItem();
            await scwin.listSync();
            await scwin.listAllDtlSync("05", dts_Dtl1);
            await scwin.listAllDtlSync("06", dts_Dtl2);
            await scwin.listAllDtlSync("07", dts_Dtl3);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.btn_New_onclick" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadError
 * @description dts_Mst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Mst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.dts_Mst_OnLoadError" });
    }
};

/**
