    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05246.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        scwin.initItem();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05246.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        await scwin.openDetail(row);
        await scwin.listAllDtlSync("05", dts_Dtl1, row);
        await scwin.listAllDtlSync("06", dts_Dtl2, row);
        await scwin.listAllDtlSync("07", dts_Dtl3, row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const status = buttonSet.status;
        $c.lc.fn_alertMsg('S');
        await scwin.listSync();
        if (status === "U") {
            dts_List.setRowPosition(scwin.selRow, 0);
            await scwin.openDetail(scwin.selRow);
        } else {
            await scwin.openDetail(dts_List.getRowCount());
        }
        await scwin.afterFile();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
        // alert_error(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05246.trs_Save_OnFail" });
    }
};

