 */
scwin.img_COM_NM_onclick = async function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        if (chk_Yn.checked) {
            // 상장폐지기업 포함 모든 목록
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }
        scwin.initItem();
        await scwin.listSync();
        await scwin.listAllDtlSync("05", dts_Dtl1);
        await scwin.listAllDtlSync("06", dts_Dtl2);
        await scwin.listAllDtlSync("07", dts_Dtl3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05246.img_COM_NM_onclick" });
    }
};

