///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
     * DELIST_REAL_INVSTG_RSN_CD 02549-상장폐지 실질심사 사유코드(10: 회생절차개시신청(삭제)  화면에서만 안보여달라고 함)
     * LIST_ELIGTY_DELIB_RSLT_CD 04414-상장적격성심의결과코드
     * AUDT_OPIN_TP_CD 01179-감사의견구분코드
     */
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

