    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listAllDtlSync
 * @description 실질심사 결과 등 그리드 조회
 * @param {String} procsCd procsCd
 * @param {*} dataSet dataSet
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listAllDtlSync = async function(procsCd, dataSet, row) {
    if (typeof row !== "undefined") {
        scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    }
    const sbmOptions = {
        id : "sbm_dataSet",
        action : "/RealInvstg.do",
        ref : "",
        target : "dataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
