 * @description 실질심사 사유 및 사유발생일 세부내역
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/RealInvstg.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    let vScrenProcTpCd;
    if (scwin.trsIdx === TRS_IDX_INSERT) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx === TRS_IDX_UPDATE) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx === TRS_IDX_DELETE) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "REG_EMP_NO", js_id);
    trs_Save.KeyName = "toinb_dataid4";
    // trs_Save.KeyValue     = "JSP(I:dtsParm1=dts_Mst)";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     COUNT : "0",
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_206,
    //     LIST_ELIGTY_TP_CD : scwin.vListEligtyTpCd
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/RealInvstg.do",
        ref : "dts_Mst,dts_Dtl1,dts_Dtl2,dts_Dtl3",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name deleteRow
 * @description 그릳드 행삭제
 * @param {*} bnd bnd
 * @param {*} grid grid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRow = async function(bnd, grid) {
    let dataSet;
    if (grid === dtl_Grd1) {
        dataSet = dts_Dtl1;
    } else if (grid === dtl_Grd2) {
        dataSet = dts_Dtl2;
    } else if (grid === dtl_Grd3) {
        dataSet = dts_Dtl3;
    }
    const fileCount = Number(dataSet.getCellData(bnd.getFocusedRowIndex(), "ATTACH_FILE_CNT"));
    if (fileCount !== 0) {
        if (confirm("관련파일이 존재합니다. 확인버튼 클릭시 관련파일이 바로 삭제됩니다. 삭제하시겠니까?")) {
            const bzProcsNo = dataSet.getCellData(bnd.getFocusedRowIndex(), "BZ_PROCS_NO");
            let procsCd = dataSet.getCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD");
            let dtlSeq = dataSet.getCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_INVSTG_DTL_SEQ");
            // dts_delRealInvstgFile.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            dts_delRealInvstgFile.insertRow();
            dts_delRealInvstgFile.setCellData(1, "bz_procs_no", bzProcsNo);
            dts_delRealInvstgFile.setCellData(1, "list_eligty_procs_cd", procsCd);
            dts_delRealInvstgFile.setCellData(1, "list_eligty_invstg_dtl_seq", dtlSeq);
            const sbmOptions = {
                id : "sbm_trs_File",
                action : "/RealInvstg.do",
                ref : "dts_delRealInvstgFile",
                target : "trs_File=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        } else {
            return;
        }
    }
    bnd.deleterow(bnd.getFocusedRowIndex());
    grid.Focus();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.initItem();
        await scwin.listSync();
        buttonSet.setInsertStatus();
    }
};

/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    buttonSet.setInsertStatus();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    dts_Mst.setCellData(1, "LIST_ELIGTY_TP_CD", scwin.vListEligtyTpCd);
    scwin.vBzProcsNo = ""; // 초기화

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if (!await scwin.eachDateCheck("3. 이의신청서 제출일", edt_EINSPRUCH_SUBMIT_DD)) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name eachDateCheck
 * @description each Date Check 처리
 * @param {*} comment comment
 * @param {*} dateComponent dateComponent
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.eachDateCheck = async function(comment, dateComponent) {
    if (dateComponent.getText() !== "") {
        if (!scwin.checkDate(dateComponent.getText())) {
            await $c.win.alert(comment + " 날짜형식을 확인하세요");
            dateComponent.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkRsnVal
 * @description check Rsn Val 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkRsnVal = async function() {
    if (dts_Dtl1.getRowCount() === 0) {
        await $c.win.alert("상장폐지 사유 및 사유발생일을 입력하세요.");
        return false;
    }
    let occrDd = "";
    let isOkDate = true;
    for (j = 1; j <= dts_Dtl1.getRowCount(); j++) {
        if (dts_Dtl1.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "") {
            await $c.win.alert(j + "번째 [1. 상장폐지 사유 및 사유발생일 '사유']를 입력하세요.");
            dtl_Grd1.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd1.focus();
            return false;
        }
        if (dts_Dtl1.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [1. 상장폐지 사유 및 사유발생일 '일자']를 입력하세요.");
            dtl_Grd1.SetColumn("OCCR_DD");
            dtl_Grd1.focus();
            return false;
        }
        occrDd = dts_Dtl1.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [1. 상장폐지 사유 및 사유발생일 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl2.getRowCount(); j++) {
        if (dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "" && dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") === "") {
            await $c.win.alert(j + "번째 [2. 감사의견 및 감사보고서 제출일 '감사의견']을 입력하세요.");
            dtl_Grd2.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd2.focus();
            return false;
        }
        if (dts_Dtl2.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [2. 감사의견 및 감사보고서 제출일 '일자']를 입력하세요.");
            dtl_Grd2.SetColumn("OCCR_DD");
            dtl_Grd2.focus();
            return false;
        }
        occrDd = dts_Dtl2.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [2. 감사의견 및 감사보고서 제출일 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl3.getRowCount(); j++) {
        if (dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "" && dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") === "") {
            await $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '결과']를 입력하세요.");
            dtl_Grd3.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd3.focus();
            return false;
        }
        if (dts_Dtl3.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '일자']를 입력하세요.");
            dtl_Grd3.SetColumn("OCCR_DD");
            dtl_Grd3.focus();
            return false;
        }
        occrDd = dts_Dtl3.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl3.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @param {*} date date
 * @returns {void}
 * @hidden N
 */
scwin.checkDate = function(date) {
    let isOk = true;
    if (date.length > 0 && !$c.ut.isDate(date)) {
        isOk = false;
    }
    return isOk;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (!await scwin.checkForm()) return;
    if (!await scwin.checkRsnVal()) return;
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Mst.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
        scwin.setBzProcsNo();
        await scwin.trs();
    }
};

/**
 * @method
 * @name setBzProcsNo
 * @description 신규 입력시 업무처리번호 셋팅
 * @param {*} bzProcsNo bzProcsNo
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(bzProcsNo) {
    const dtl1Row = dts_Dtl1.getRowCount();
    dts_Dtl1.setBroadcast(false);
    for (k = 1; k <= dts_Dtl1.getRowCount(); k++) {
        dts_Dtl1.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl1.setBroadcast(true, true);
    dts_Dtl2.setBroadcast(false);
    for (k = 1; k <= dts_Dtl2.getRowCount(); k++) {
        dts_Dtl2.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl2.setBroadcast(true, true);
    dts_Dtl3.setBroadcast(false);
    for (k = 1; k <= dts_Dtl3.getRowCount(); k++) {
        dts_Dtl3.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl3.setBroadcast(true, true);
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!await scwin.checkForm()) return;
    if (!await scwin.checkRsnVal()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.selRow = dts_List.getRowPosition();
    await scwin.trs();
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.trs();
};

/**
 * @method
 * @name addRow
 * @description 그리드 행추가
 * @param {*} bnd bnd
 * @param {*} grid grid
 * @param {*} type type
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function(bnd, grid, type) {
    bnd.addRow();
    dts_Mst.getRowPosition();
    grid.Focus();
    bnd.setCellData(bnd.getFocusedRowIndex(), "BZ_PROCS_NO", scwin.vBzProcsNo);
    if (type === "E") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "05");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "DELIST_REAL_INVSTG_RSN_CD");
    } else if (type === "F") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "06");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "AUDT_OPIN_TP_CD");
    } else if (type === "G") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "07");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "LIST_ELIGTY_DELIB_RSLT_CD");
    }
};

/**
 * @method
 * @name searchGrdCode
 * @description 코드값을 그리드 콤보박스에 설정
 * @param {*} codeName codeName
 * @param {*} grd grd
 * @returns {void}
 * @hidden N
 */
scwin.searchGrdCode = function(codeName, grd) {
    let strCbdReason = "' ':"; // 초기값
    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") === codeName) {
            if (codeName === "DELIST_REAL_INVSTG_RSN_CD") {
                if (dts_Cod.getCellData(k, "VALUE") !== "10") {
                    strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
                }
            } else {
                strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
            }
        }
    }
    grd.setColumnProp('LIST_ELIGTY_PROCS_RSN_VAL', 'Data', strCbdReason);
};

// 첨부파일등록(이의신청서)

/**
 * @method
 * @name attachFileDtl
 * @description attach File Dtl 처리
 * @param {String} listEligtyProcsCd listEligtyProcsCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachFileDtl = async function(listEligtyProcsCd) {
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert("심사  내용을 저장 한 후, 파일을 등록하여 주십시오.");
        return;
    }
    let url = "/lstproc/ULDSTF05241_FILE.gfm?BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + listEligtyProcsCd;
    await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 등록", 100, 100, 850, 450, "window");
};

/**
 * @method
 * @name afterFile
 * @description after File 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.afterFile = async function() {
    await scwin.listAllDtlSync("05", dts_Dtl1, dts_List.getRowPosition());
    await scwin.listAllDtlSync("06", dts_Dtl2, dts_List.getRowPosition());
    await scwin.listAllDtlSync("07", dts_Dtl3, dts_List.getRowPosition());
};

/**
 * @method
 * @name attachFile
 * @description 첨부파일등록
 * @param {*} dataSet dataSet
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachFile = async function(dataSet, row) {
    if (dataSet.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ") === "") {
        await $c.win.alert("데이터를 저장 한 후, 파일을 등록하여 주십시오.");
    } else if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert("심사  내용을 저장 한 후, 심의안건을 등록하여 주십시오.");
    } else {
        let procsCd = dataSet.getCellData(row, "LIST_ELIGTY_PROCS_CD");
        let dtlSeq = dataSet.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
        let url = "/lstproc/ULDSTF05241_FILE.gfm?BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsCd + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq;
        await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 등록", 100, 100, 850, 450, "window");
    }
};

/**
 * @method
 * @name callElasticFileNoti
 * @description call Elastic File Noti 처리
 * @param {*} callType callType
 * @returns {void}
 * @hidden N
 */
scwin.callElasticFileNoti = function(callType) {
    const callUrl = "/index/tbld_eligty_invstg_attach/kafka";
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "notiEligtyFile",
            bz_procs_no: scwin.vBzProcsNo,
            url: callUrl
        },
        async: true
    });
};

